import{j as e}from"./blog-pages-CPaMOKsP.js";import{P as a}from"./compare-pages-DL36og6S.js";const r=[{factor:"Connection method",atlantis:"REST + Family Manager APIs",competitor:"GE Vernova APM exposes REST APIs over OAuth2; legacy SOAP available"},{factor:"Supported APM versions",atlantis:"GE APM 4.6+, GE Vernova APM (current)",competitor:"—"},{factor:"Authentication",atlantis:"OAuth2 client credentials",competitor:"—"},{factor:"Asset master sync",atlantis:"Bi-directional, GE Vernova APM master of record",competitor:"—"},{factor:"Inspection findings → APM",atlantis:"Inspection records with FFS / RBI summary and deep link back to Atlantis",competitor:"—"},{factor:"RBI library sync",atlantis:"One-time + ongoing — see Meridium APM integration page for detail",competitor:"—"},{factor:"Deployment time",atlantis:"4–6 weeks typical",competitor:"—"},{factor:"Power generation modules",atlantis:"Native support for GE Vernova&rsquo;s power-gen-specific APM modules (turbines, generators, balance-of-plant)",competitor:"—"}],i=[{question:"Is GE Vernova APM the same as GE APM?",answer:"Yes — same product line, post-2024 corporate badging. GE split into three companies in 2024: GE Aerospace, GE HealthCare, and GE Vernova. The APM products went to GE Vernova. The platform code base, data model, and APIs are continuous from Meridium → GE APM → GE Vernova APM. Our integration supports the entire lineage."},{question:"How does this differ from the Meridium APM integration page?",answer:"Functionally identical — they describe the same integration. The Meridium APM page covers the legacy / pre-Vernova product naming and is geared toward customers with older installs. This page covers the current GE Vernova APM product naming and includes notes specific to the power generation APM modules (turbines, generators, balance-of-plant, transmission) that are most relevant to Vernova&rsquo;s customer base. The technical architecture is the same."},{question:"What about GE Vernova&rsquo;s power-gen specific APM modules?",answer:"GE Vernova has deepened the APM modules covering gas turbines, steam turbines, generators, transformers, and balance-of-plant equipment. Atlantis integrates with these modules natively — turbine blade inspection records, generator winding inspections, transformer DGA results, etc. flow into the appropriate Atlantis equipment record. For wind farm assets (a strategic Vernova focus area), Atlantis adds blade inspection workflow native to the platform."},{question:"Migration vs coexistence?",answer:"Same options as the Meridium APM page: full APM-to-Atlantis migration over 10–14 weeks, or coexistence pattern where APM remains the system of record for the corporate RBI library and long-term archive while Atlantis is the daily inspection capture and 3D twin layer. Most GE Vernova APM customers choose coexistence for the first 12–24 months; some migrate fully when the APM contract is up for renewal."},{question:"Are there any GE-specific gotchas to know about?",answer:"A few. (1) GE Vernova APM&rsquo;s authentication requires a service account with specific Family Manager privileges — your APM admin needs to provision this. (2) Some custom Family templates from older Meridium installs need mapping work — we handle this during scoping. (3) The recent shift from on-prem SQL Server to GE Vernova&rsquo;s cloud-hosted APM changes some authentication and rate-limit details — we have current connector code paths for both."}];function l(){const n={"@context":"https://schema.org","@graph":[{"@type":"SoftwareApplication",name:"Atlantis Digital Twin — GE Vernova APM Integration",applicationCategory:"BusinessApplication",operatingSystem:"Web",description:"GE Vernova APM (formerly GE APM, originally Meridium) integration: REST + Family Manager APIs, bi-directional asset sync, RBI library, inspection records. Power-gen module support.",offers:{"@type":"Offer",availability:"https://schema.org/InStock"},provider:{"@type":"Organization",name:"Atlantis NDT"}},{"@type":"Article",headline:"Atlantis Digital Twin — GE Vernova APM Integration [2026]",datePublished:"2026-05-09",dateModified:"2026-05-09",author:{"@type":"Person",name:"Anoop Rayavarapu"},publisher:{"@type":"Organization",name:"Atlantis NDT"}},{"@type":"FAQPage",mainEntity:i.map(t=>({"@type":"Question",name:t.question,acceptedAnswer:{"@type":"Answer",text:t.answer}}))}]};return e.jsx(a,{title:"Atlantis Digital Twin — GE Vernova APM Integration: Power Gen + Oil & Gas [2026]",description:"GE Vernova APM (post-2024 split, formerly GE APM / Meridium) integration: REST + Family Manager APIs, bi-directional asset sync, RBI library, native power-gen module support.",canonical:"https://atlantisndt.com/integrations/ge-vernova-apm",eyebrow:"Integration",h1:"Atlantis Digital Twin — GE Vernova APM Integration: Power Gen + Oil & Gas [2026]",intro:"GE Vernova APM (post-2024 split, formerly GE APM and originally Meridium) integration. REST + Family Manager APIs, bi-directional asset sync, RBI library, native support for power-gen specific modules. 4–6 weeks to production.",heroGradient:"from-cyan-700 to-emerald-800",competitorLabel:"Notes",compareRows:r,faqs:i,related:[{href:"/integrations/meridium-apm",title:"Meridium APM Integration",blurb:"Legacy / pre-Vernova naming — same integration."},{href:"/compare/atlantis-dt-vs-ge-predix",title:"vs GE Predix / APM (Comparison)",blurb:"When to use each, when to migrate."},{href:"/integrations/aspen-mtell",title:"Aspen Mtell Integration",blurb:"Rotating-equipment ML coverage."},{href:"/digital-twins/wind-farm",title:"Digital Twin for Wind Farms",blurb:"Strategic Vernova focus area — blade inspection workflow native."},{href:"/digital-twins",title:"Atlantis Digital Twin",blurb:"Product page — features, pricing, case studies."},{href:"/contact",title:"Book a Scoping Call",blurb:"60-minute call with a Level III consultant + integration architect."}],ctaTitle:"Plug Atlantis Into Your GE Vernova APM",ctaSubtitle:"Bring your APM org and a sample asset Family export. We’ll show the integration in 30 minutes.",structuredData:n,bodyChildren:e.jsxs(e.Fragment,{children:[e.jsx("h2",{children:"Architecture overview"}),e.jsx("p",{children:"Atlantis Digital Twin connects to GE Vernova APM via the APM REST APIs and Family Manager APIs over OAuth2. A dedicated APM integration user is provisioned with read access to Equipment, Functional Location, RBI Component, and Inspection Family records, and write access to Inspection records (where Atlantis pushes findings back). We do not require APM administrator privileges and do not modify the APM schema."}),e.jsx("h2",{children:"The Vernova split — what it means for integration"}),e.jsx("p",{children:"The 2024 GE corporate split moved the APM products to GE Vernova / GE Digital. The platform code base, data model, and APIs are continuous from Meridium → GE APM → GE Vernova APM, so existing integrations don’t break at the split. What changed is product positioning — Vernova is investing more deeply in power-generation specific APM modules (gas turbines, steam turbines, generators, transformers, balance-of-plant, and increasingly wind / solar / energy storage). For oil & gas customers the trajectory is less aggressive but the product remains supported."}),e.jsx("h2",{children:"Power generation specific notes"}),e.jsx("p",{children:"Atlantis covers the inspection workflows specific to power generation APM modules: turbine blade NDT (PT, MT, eddy current on combustion turbine blades; UT and PT on steam turbine rotors), generator winding inspections, transformer DGA result tracking and trending, balance-of-plant tank/vessel/piping integrity, and for wind farm operators, blade inspection workflows including drone-based capture. These flow into the GE Vernova APM equipment records and contribute to the asset health scoring."}),e.jsx("h2",{children:"Two deployment patterns (same as Meridium page)"}),e.jsx("h3",{children:"Coexistence (most common)"}),e.jsx("p",{children:"GE Vernova APM remains the system of record for the corporate RBI library and integrity master data. Atlantis becomes the daily inspection capture tool, FFS engine, and 3D twin layer. Findings flow Atlantis → APM as Inspection records. 4–6 weeks to production."}),e.jsx("h3",{children:"Full migration"}),e.jsx("p",{children:"10–14 week APM-to-Atlantis migration. Equipment master, RBI library, FFS history, inspection events, CML registers all migrate via Family Manager APIs. APM is decommissioned at the end. TCO typically drops 40–60%, adoption climbs sharply."})]})})}export{l as default};
